Which number line shows $x\le6$?
[tikz]
\begin{tikzpicture}
\node[left] at (0.4,0) {$A$};
\draw[{Stealth}-{Stealth}] (0.55,0)--(4.85,0);
\foreach \v in {2,...,10} {\draw (0.45*\v,0.08)--(0.45*\v,-0.08); \node[below,font=\tiny] at (0.45*\v,-0.1) {$\v$};}
\draw[very thick,-{Stealth}] (2.7,0)--(0.75,0);
\draw[fill=white] (2.7,0) circle (2.4pt);
\node[left] at (0.4,-1.3) {$B$};
\draw[{Stealth}-{Stealth}] (0.55,-1.3)--(4.85,-1.3);
\foreach \v in {2,...,10} {\draw (0.45*\v,-1.22)--(0.45*\v,-1.38); \node[below,font=\tiny] at (0.45*\v,-1.4) {$\v$};}
\draw[very thick,-{Stealth}] (2.7,-1.3)--(4.65,-1.3);
\fill (2.7,-1.3) circle (2.4pt);
\node[left] at (0.4,-2.6) {$C$};
\draw[{Stealth}-{Stealth}] (0.55,-2.6)--(4.85,-2.6);
\foreach \v in {2,...,10} {\draw (0.45*\v,-2.52)--(0.45*\v,-2.68); \node[below,font=\tiny] at (0.45*\v,-2.7) {$\v$};}
\draw[very thick,-{Stealth}] (2.7,-2.6)--(0.75,-2.6);
\fill (2.7,-2.6) circle (2.4pt);
\node[left] at (0.4,-3.9) {$D$};
\draw[{Stealth}-{Stealth}] (0.55,-3.9)--(4.85,-3.9);
\foreach \v in {2,...,10} {\draw (0.45*\v,-3.82)--(0.45*\v,-3.98); \node[below,font=\tiny] at (0.45*\v,-4) {$\v$};}
\draw[very thick,-{Stealth}] (2.7,-3.9)--(4.65,-3.9);
\draw[fill=white] (2.7,-3.9) circle (2.4pt);
\end{tikzpicture}
[/tikz]

Which number line shows $x>1$?
[tikz]
\begin{tikzpicture}
\node[left] at (-1.85,0) {$A$};
\draw[{Stealth}-{Stealth}] (-1.7,0)--(2.6,0);
\foreach \v in {-3,...,5} {\draw (0.45*\v,0.08)--(0.45*\v,-0.08); \node[below,font=\tiny] at (0.45*\v,-0.1) {$\v$};}
\draw[very thick,-{Stealth}] (0.45,0)--(2.4,0);
\fill (0.45,0) circle (2.4pt);
\node[left] at (-1.85,-1.3) {$B$};
\draw[{Stealth}-{Stealth}] (-1.7,-1.3)--(2.6,-1.3);
\foreach \v in {-3,...,5} {\draw (0.45*\v,-1.22)--(0.45*\v,-1.38); \node[below,font=\tiny] at (0.45*\v,-1.4) {$\v$};}
\draw[very thick,-{Stealth}] (0.45,-1.3)--(2.4,-1.3);
\draw[fill=white] (0.45,-1.3) circle (2.4pt);
\node[left] at (-1.85,-2.6) {$C$};
\draw[{Stealth}-{Stealth}] (-1.7,-2.6)--(2.6,-2.6);
\foreach \v in {-3,...,5} {\draw (0.45*\v,-2.52)--(0.45*\v,-2.68); \node[below,font=\tiny] at (0.45*\v,-2.7) {$\v$};}
\draw[very thick,-{Stealth}] (0.45,-2.6)--(-1.5,-2.6);
\draw[fill=white] (0.45,-2.6) circle (2.4pt);
\node[left] at (-1.85,-3.9) {$D$};
\draw[{Stealth}-{Stealth}] (-1.7,-3.9)--(2.6,-3.9);
\foreach \v in {-3,...,5} {\draw (0.45*\v,-3.82)--(0.45*\v,-3.98); \node[below,font=\tiny] at (0.45*\v,-4) {$\v$};}
\draw[very thick,-{Stealth}] (0.45,-3.9)--(-1.5,-3.9);
\fill (0.45,-3.9) circle (2.4pt);
\end{tikzpicture}
[/tikz]

Which inequality is shown by this number line?
[tikz]
\begin{tikzpicture}
\draw[{Stealth}-{Stealth}] (-0.9,0)--(3.9,0);
\foreach \v in {-1,...,7} {\draw (0.5*\v,0.12)--(0.5*\v,-0.12); \node[below] at (0.5*\v,-0.16) {$\v$};}
\draw[very thick,-{Stealth}] (1.5,0)--(3.7,0);
\fill (1.5,0) circle (2.4pt);
\node[right] at (4,0) {$x$};
\end{tikzpicture}
[/tikz]

Which inequality is shown by this number line?
