Which number line shows the values that satisfy **both** $x\ge-4$ and $x<1$?
[tikz]
\begin{tikzpicture}
\node[left] at (-3.2,0) {$A$};
\draw[{Stealth}-{Stealth}] (-3.05,0)--(1.7,0);
\foreach \v in {-6,...,3} {\draw (0.45*\v,0.08)--(0.45*\v,-0.08); \node[below,font=\tiny] at (0.45*\v,-0.1) {$\v$};}
\draw[very thick] (-1.8,0)--(0.45,0);
\draw[fill=white] (-1.8,0) circle (2.4pt);
\fill (0.45,0) circle (2.4pt);
\node[left] at (-3.2,-1.3) {$B$};
\draw[{Stealth}-{Stealth}] (-3.05,-1.3)--(1.7,-1.3);
\foreach \v in {-6,...,3} {\draw (0.45*\v,-1.22)--(0.45*\v,-1.38); \node[below,font=\tiny] at (0.45*\v,-1.4) {$\v$};}
\draw[very thick] (-1.8,-1.3)--(0.45,-1.3);
\fill (-1.8,-1.3) circle (2.4pt);
\fill (0.45,-1.3) circle (2.4pt);
\node[left] at (-3.2,-2.6) {$C$};
\draw[{Stealth}-{Stealth}] (-3.05,-2.6)--(1.7,-2.6);
\foreach \v in {-6,...,3} {\draw (0.45*\v,-2.52)--(0.45*\v,-2.68); \node[below,font=\tiny] at (0.45*\v,-2.7) {$\v$};}
\draw[very thick] (-1.8,-2.6)--(0.45,-2.6);
\draw[fill=white] (-1.8,-2.6) circle (2.4pt);
\draw[fill=white] (0.45,-2.6) circle (2.4pt);
\node[left] at (-3.2,-3.9) {$D$};
\draw[{Stealth}-{Stealth}] (-3.05,-3.9)--(1.7,-3.9);
\foreach \v in {-6,...,3} {\draw (0.45*\v,-3.82)--(0.45*\v,-3.98); \node[below,font=\tiny] at (0.45*\v,-4) {$\v$};}
\draw[very thick] (-1.8,-3.9)--(0.45,-3.9);
\fill (-1.8,-3.9) circle (2.4pt);
\draw[fill=white] (0.45,-3.9) circle (2.4pt);
\end{tikzpicture}
[/tikz]

